(function(root){
 const money=n=>'¥'+(n/100).toLocaleString('zh-CN',{maximumFractionDigits:2});
 const percent=n=>n>0&&n<.001?'<0.1%':(n*100).toFixed(1)+'%';
 function compact(n,max=13){const full=money(n);if(full.length<=max)return full;return '¥'+(n/100/(Math.abs(n)>=1e10?1e8:1e4)).toLocaleString('zh-CN',{maximumFractionDigits:2})+(Math.abs(n)>=1e10?'亿':'万');}
 function donutLayout(parts,width=320){const rows=parts.filter(p=>p.cents>0),total=rows.reduce((n,p)=>n+p.cents,0);if(!Number.isSafeInteger(total))throw Error('图表金额超出计算范围。');width=Math.max(280,Math.min(440,width));let angle=-Math.PI/2;const items=rows.map(p=>{const share=p.cents/total,mid=angle+share*Math.PI;angle+=share*Math.PI*2;return{...p,share,angle:mid,side:Math.cos(mid)<0?'left':'right'};});const count=Math.max(0,...['left','right'].map(side=>items.filter(p=>p.side===side).length)),height=Math.max(270,count*51+30),cx=width/2,cy=height/2,radius=Math.min(72,width*.18);for(const side of ['left','right']){const list=items.filter(p=>p.side===side).sort((a,b)=>Math.sin(a.angle)-Math.sin(b.angle));let last=0;for(const p of list){p.y=Math.max(cy+Math.sin(p.angle)*(radius+34)-16,last+51);last=p.y;}if(list.length&&list.at(-1).y>height-42){last=height-42;for(const p of list.slice().reverse()){p.y=Math.min(p.y,last);last=p.y-51;}}}return{width,height,cx,cy,radius,items,total};}
 function lineLabels(points,{left,top,right,bottom,all=false}){const result=[],boxes=[];const ordered=points.slice().sort((a,b)=>Number(!!b.last)-Number(!!a.last)||Number(!!b.family)-Number(!!a.family)||a.x-b.x);for(const p of ordered){const width=Math.min(right-left,Math.max(28,p.text.length*6.1+4)),x=Math.min(right-width/2,Math.max(left+width/2,p.x));let found=null;const offsets=[-14,19,-31,36,-48,53,-65,70,-82,87,-99,104];for(const offset of offsets){const y=Math.max(top+12,Math.min(bottom-2,p.y+offset)),box={left:x-width/2,right:x+width/2,top:y-11,bottom:y+3};if(!boxes.some(b=>box.left<b.right+5&&box.right>b.left-5&&box.top<b.bottom+3&&box.bottom>b.top-3)){found={...p,labelX:x,labelY:y,box};break;}}if(!found&&all){for(let y=top+12;y<=bottom-2;y+=18){const box={left:x-width/2,right:x+width/2,top:y-11,bottom:y+3};if(!boxes.some(b=>box.left<b.right+5&&box.right>b.left-5&&box.top<b.bottom+3&&box.bottom>b.top-3)){found={...p,labelX:x,labelY:y,box};break;}}}if(found){boxes.push(found.box);result.push(found);}}return result;}
 const api={money,percent,compact,donutLayout,lineLabels};if(typeof module!=='undefined'&&module.exports){module.exports=api;return;}root.FamilyChartLabels=api;
 const node=(tag,attrs={})=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);return n;};
 api.donut=function(parts,{width=320,title,total,color,onSelect=()=>{},onFocus=()=>{},selected=null}){const l=donutLayout(parts,width),svg=node('svg',{viewBox:`0 0 ${l.width} ${l.height}`,role:'img','aria-label':title});svg.classList.add('income-donut','annotated-donut');let offset=0;for(const p of l.items){const description=p.name+'：'+money(p.cents)+' · '+percent(p.share),circle=node('circle',{cx:l.cx,cy:l.cy,r:l.radius,fill:'none',stroke:color(p.key),'stroke-width':22,pathLength:100,'stroke-dasharray':p.share*100+' '+(100-p.share*100),'stroke-dashoffset':-offset,transform:`rotate(-90 ${l.cx} ${l.cy})`,tabindex:0,role:'button','aria-label':description,'aria-pressed':String(selected===p.key)});const caption=node('title');caption.textContent=description;circle.append(caption);circle.onclick=()=>onSelect(p.key);circle.onpointerenter=circle.onfocus=()=>onFocus(description);circle.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();onSelect(p.key);}};svg.append(circle);offset+=p.share*100;}
 for(const p of l.items){const left=p.side==='left',x=left?4:l.width-4,startX=l.cx+Math.cos(p.angle)*(l.radius+13),startY=l.cy+Math.sin(p.angle)*(l.radius+13),endX=left?l.cx-l.radius-18:l.cx+l.radius+18,group=node('g',{class:'pie-callout',tabindex:0,role:'button','aria-label':p.name+' '+money(p.cents)+' '+percent(p.share)});svg.append(node('polyline',{points:`${startX},${startY} ${endX},${p.y+27} ${left?x+25:x-25},${p.y+27}`,fill:'none',stroke:color(p.key),'stroke-width':1,opacity:.65}));const full=node('title');full.textContent=p.name+'：'+money(p.cents)+' · '+percent(p.share);group.append(full);for(const [dy,text,cls]of [[0,p.name.length>10?p.name.slice(0,9)+'…':p.name,'pie-category'],[15,compact(p.cents,13),'pie-amount'],[29,percent(p.share),'pie-percentage']]){const t=node('text',{x,y:p.y+dy,'text-anchor':left?'start':'end',fill:'currentColor',class:cls,'font-size':11});t.textContent=text;group.append(t);}group.onclick=()=>onSelect(p.key);group.onpointerenter=group.onfocus=()=>onFocus(full.textContent);group.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();onSelect(p.key);}};svg.append(group);}
 const center=node('text',{x:l.cx,y:l.cy+5,'text-anchor':'middle',fill:'currentColor','font-size':14,class:'pie-total'});center.textContent=compact(total,11);const exact=node('title');exact.textContent=money(total);center.append(exact);svg.append(center);return svg;};
 api.lineSVG=function(points,bounds){return lineLabels(points,bounds).map(p=>`<g class="point-value-label"><path d="M${p.x},${p.y} L${p.labelX},${p.labelY+3}" fill="none" stroke="${p.color}" stroke-width=".7" opacity=".4"/><text x="${p.labelX}" y="${p.labelY}" text-anchor="middle" style="fill:${p.color}" font-size="10">${p.text}</text></g>`).join('');};
})(globalThis);
